<?php
require_once __DIR__.'/../includes/layout.php';$u=require_login('recruiter');$q=db()->prepare('SELECT o.*,COUNT(a.id) applicants FROM offers o LEFT JOIN applications a ON a.offer_id=o.id WHERE o.recruiter_id=? GROUP BY o.id ORDER BY o.created_at DESC');$q->execute([$u['id']]);$rows=$q->fetchAll();page_header('Mes offres');
?><p><a class="btn" href="<?=h(url('recruiter/offer_form.php'))?>">+ Publier une offre</a></p><div class="table-wrap"><table><tr><th>Offre</th><th>Type</th><th>Statut</th><th>Candidatures</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['type'])?></td><td><?=h($r['status'])?></td><td><?=h((string)$r['applicants'])?></td><td><a href="<?=h(url('recruiter/offer_form.php?id='.$r['id']))?>">Modifier</a> · <a href="<?=h(url('recruiter/dashboard.php?offer='.$r['id']))?>">Candidats</a></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p>Vous n’avez pas encore publié d’offre.</p><?php endif;page_footer();?>